window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-26da96d2ddd408c4"]={"versions": [{"id": "FIG-26da96d2ddd408c4", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Activation</code>) zur Darstellung des Aktivierungsprozesses innerhalb des AUTOSAR Adaptive Platform Update and Configuration Management (UCM). Es beschreibt den nachgelagerten Ablauf nach erfolgreicher Paketverarbeitung zwischen einem externen Diagnosetool bzw. einer OEM-Applikation und dem UCM-Dienst zur Umschaltung und Inbetriebnahme aktualisierter Softwarekomponenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Diagnostic Application (OEM specific)</code>: Akteur/Client, der über die UCM-Dienstschnittstelle den Aktivierungs- und Finalisierungsvorgang anstößt und Statusupdates überwacht.</li>\n<li><code>:UCM</code> (<code>«ServiceProvider»</code>): Dienstanbieter der Adaptive Platform (Update and Configuration Management), der Paketabhängigkeiten prüft, Partitionen synchronisiert, Software neu startet und den Statuswechsel verwaltet.</li>\n<li>Schnittstellenmethoden & Events:</li>\n<li><code>Subscribe(CurrentStatus)</code>: Ereignis-Abonnement zur Zustandsüberwachung.</li>\n<li><code>Activate(): ActivateReturnType</code>: Synchrone Dienstmethode zur Initiierung der Aktivierung.</li>\n<li><code>Finish(): FinishReturnType</code>: Synchrone Dienstmethode zum Abschluss des Update-Vorgangs.</li>\n<li><code>:READY</code>, <code>CurrentStatus= :ACTIVATING</code>: Zustands- und Ereignisnachrichten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Diagnostic Application</code> abonniert über <code>Subscribe(CurrentStatus)</code> den aktuellen Status des UCM und erhält die Rückmeldung <code>:READY</code>.</li>\n<li>Die Diagnose-Applikation ruft synchron <code>Activate(): ActivateReturnType</code> am UCM auf.</li>\n<li>Das UCM führt eine interne Abhängigkeitsprüfung durch (<code>checkPackageDependencies()</code>) und antwortet synchron mit <code>:ActivateReturnType</code>.</li>\n<li>Das UCM publiziert asynchron die Statusänderung <code>CurrentStatus= :ACTIVATING</code> an die abonnierte Applikation.</li>\n<li>Das UCM führt intern bei Bedarf einen Neustart der installierten Software durch (<code>restartInstalledSoftwareIfNeeded()</code>).</li>\n<li>Die Diagnose-Applikation ruft <code>Finish(): FinishReturnType</code> am UCM auf.</li>\n<li>Das UCM führt intern die Partitionsumschaltung und -synchronisation aus (<code>swapPartitionsAndSynchronizeThem()</code>) und quittiert den Aufruf synchron mit <code>:FinishReturnType</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Aktivierungsablauf ist zweistufig ausgelegt (<code>Activate</code> gefolgt von <code>Finish</code>). Fehler bei <code>checkPackageDependencies()</code> führen zum Abbruch vor dem Softwareneustart. <code>swapPartitionsAndSynchronizeThem()</code> verankert das A/B-Partitions- bzw. Dual-Bank-Konzept als Ausführungsphase nach erfolgreichem <code>Finish()</code>. Implementierer müssen sicherstellen, dass die Statusbenachrichtigung (<code>CurrentStatus</code>) vor dem Abschluss interner Neustarts publiziert wird.</p>"}, {"id": "FIG-0c6ab6398bf753e6", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Modellierung des UCM-Aktivierungsprozesses im Zusammenspiel mit dem AUTOSAR Adaptive State Management. Es visualisiert die Interaktion zur Überführung der Funktionsgruppen in den Verifikationszustand zwischen einer Diagnose-Applikation, der UCM-Dienstinstanz (<code>:External Reference</code>) und dem <code>State Management</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Diagnostic Application (OEM specific)</code>: Akteur/Client, der Aktivierung und Finalisierung auslöst und Statusaktualisierungen empfängt.</li>\n<li><code>:External Reference</code> (<code>«ServiceProvider»</code>): UCM-Service-Instanz, die Abhängigkeiten prüft, die Zustandsänderung beim State Management anfordert und nach Abschluss aufräumt.</li>\n<li><code>State Management</code> (<code>«ServiceSwComponentType»</code>): Plattformkomponente zur Koordination von Funktionsgruppen und Ausführungszuständen im System.</li>\n<li>Schnittstellen und Ereignisse:</li>\n<li><code>Subscribe(CurrentStatus)</code>, <code>CurrentStatus(Activating)</code>, <code>CurrentStatus(Activated)</code></li>\n<li><code>Activate(): ActivateReturnType</code></li>\n<li><code>Subscribe(FunctionGroupState_{Function Group})</code></li>\n<li><code>FunctionGroupState_{Function Group} (Verify)</code></li>\n<li><code>Finish(): FinishReturnType</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>Diagnostic Application</code> abonniert über <code>Subscribe(CurrentStatus)</code> den Status des UCM und empfängt <code>:READY</code>.</li>\n<li><code>Diagnostic Application</code> ruft <code>Activate(): ActivateReturnType</code> an <code>:External Reference</code> auf.</li>\n<li><code>:External Reference</code> führt intern <code>checkPackageDependencies()</code> aus und liefert <code>:ActivateReturnType</code> zurück.</li>\n<li><code>:External Reference</code> sendet <code>CurrentStatus(Activating)</code> an die <code>Diagnostic Application</code>.</li>\n<li><code>:External Reference</code> abonniert bei <code>State Management</code> den Funktionsgruppenzustand via <code>Subscribe(FunctionGroupState_{Function Group})</code>.</li>\n<li><code>State Management</code> meldet den Übergang in den Verifikationszustand zurück über <code>FunctionGroupState_{Function Group} (Verify)</code>.</li>\n<li><code>:External Reference</code> meldet <code>CurrentStatus(Activated)</code> an die <code>Diagnostic Application</code>.</li>\n<li><code>Diagnostic Application</code> sendet <code>Finish(): FinishReturnType</code> an <code>:External Reference</code>.</li>\n<li><code>:External Reference</code> führt eine interne Bereinigung durch (<code>Cleanup()</code>) und antwortet synchron mit <code>:FinishReturnType</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Verifikation des Updates erfolgt koordiniert über das State Management: Die UCM-Aktivierung gilt erst nach Erreichen des Zustands <code>Verify</code> der relevanten Funktionsgruppen als abgeschlossen (<code>CurrentStatus(Activated)</code>). Vor dem Aufruf von <code>Finish()</code> verbleibt das System im aktivierten Zustand. Das Bereinigen temporärer Daten (<code>Cleanup()</code>) ist zwingend an den <code>Finish()</code>-Aufruf gebunden.</p>"}, {"id": "FIG-9ef0817a813c9118", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm des verteilten UCM-Aktivierungsprozesses in einer Multi-UCM-Architektur (UCM Master und UCM Subordinates) unter Einbindung des State Managements (<code>SM</code>). Das Diagramm gliedert den Ablauf über vertikale Zustandskontexte (<code>Ready</code>, <code>Activating</code>, <code>Verifying</code>, <code>Activated</code>, <code>Cleaning-up</code>) sowie Schleifen- und Alternativblöcke zur clusterweisen Aktualisierung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>UCM master</code> (<code>(from Actors)</code>): Übergeordneter Koordinator, der die Aktivierung und den finalen Abschluss über unterlagerte UCM-Instanzen steuert.</li>\n<li><code>UCM sub 1</code> (<code>(from Actors)</code>): Untergeordnete UCM-Instanz, die Update-Sessions initiiert, Manifeste und Abhängigkeiten auswertet sowie Umschalt- und Verifikationsschritte ausführt.</li>\n<li><code>SM</code> (<code>(from Actors)</code>): State Management zur Steuerung der Session-Zustände und Vorbereitung/Verifikation der Funktionsgruppen (<code>vector&lt;FunctionGroup&gt;</code>).</li>\n<li>Schnittstellen & Operationen:</li>\n<li><code>Activate()</code>, <code>Finish()</code>, <code>:Activation success</code></li>\n<li><code>StartUpdateSession()</code>, <code>:ReadyForUpdate</code></li>\n<li><code>PrepareUpdate(vector&lt;FunctionGroup&gt;)</code>, <code>:Prepared</code></li>\n<li><code>VerifyUpdate(vector&lt;FunctionGroup&gt;)</code>, <code>:Verified</code></li>\n<li><code>StopUpdateSession()</code></li>\n<li><code>ResetMachine()</code> (optional bei Maschinen-Reset)</li>\n<li>Interne Methoden: <code>DependencyCheck()</code>, <code>Symlinks or A/B switch()</code>, <code>Reparse Manifests()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Zustand <code>Ready</code>: <code>UCM master</code> sendet <code>Activate()</code> an <code>UCM sub 1</code>.</li>\n<li>Übergang nach <code>Activating</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>UCM sub 1</code> führt intern <code>DependencyCheck()</code> aus.</li>\n<li><code>UCM sub 1</code> ruft an <code>SM</code> <code>StartUpdateSession()</code> auf und erhält <code>:ReadyForUpdate</code>.</li>\n<li>In einer Schleife (<code>loop for each SoftwareCluster</code>) sendet <code>UCM sub 1</code> <code>PrepareUpdate(vector&lt;FunctionGroup&gt;)</code> an <code>SM</code> und erhält jeweils <code>:Prepared</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Übergang nach <code>Verifying</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>UCM sub 1</code> vollzieht intern <code>Symlinks or A/B switch()</code>.</li>\n<li>Verzweigung <code>alt ReparseManifest</code>:</li>\n<li>Pfad <code>[Reset]</code>: <code>UCM sub 1</code> initiiert <code>ResetMachine()</code> an <code>SM</code>.</li>\n<li>Pfad <code>[No Reset]</code>: <code>UCM sub 1</code> führt intern <code>Reparse Manifests()</code> aus.</li>\n<li>In einer Schleife (<code>loop for each SoftwareCluster</code>) ruft <code>UCM sub 1</code> an <code>SM</code> <code>VerifyUpdate(vector&lt;FunctionGroup&gt;)</code> auf und erhält <code>:Verified</code>.</li>\n<li><code>UCM sub 1</code> meldet <code>:Activation success</code> an <code>UCM master</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zustand <code>Activated</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>UCM master</code> koordiniert parallel wartende Subordinates und sendet <code>Finish()</code> an <code>UCM sub 1</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zustand <code>Cleaning-up</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>UCM sub 1</code> ruft an <code>SM</code> <code>StopUpdateSession()</code> auf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Iterative Clusterverarbeitung: <code>PrepareUpdate</code> und <code>VerifyUpdate</code> werden clusterweise mit Vektoren von Funktionsgruppen parametrisiert.</li>\n<li>Maschinen-Reset vs. Re-Parsing: Das Softwarepaket-Manifest (<code>SWP Manifest</code>) steuert über den Branch <code>[Reset]</code> die Ausführung von <code>ResetMachine()</code>; im Branch <code>[No Reset]</code> erfolgt <code>Reparse Manifests()</code> (Entwurfsstatus, alternativ durch Core SM nach erstem Verify ausführbar).</li>\n<li>Koordination: <code>UCM master</code> synchronisiert mehrere UCM Subs, indem <code>Finish()</code> erst gesendet wird, wenn alle Subordinates <code>:Activation success</code> gemeldet haben.</li>\n<li>Beendigung: Der Bereinigungsprozess schließt die Update-Session über <code>StopUpdateSession()</code> am State Management explizit ab.</li>\n</ul>"}], "trans": [{"from": "FIG-26da96d2ddd408c4", "to": "FIG-0c6ab6398bf753e6", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Integration von State Management: Die Entität <code>«ServiceSwComponentType» State Management</code> wird neu eingebunden.</li>\n<li>Neuer Benachrichtigungsablauf: <code>:External Reference</code> abonniert <code>Subscribe(FunctionGroupState_{Function Group})</code> bei State Management und empfängt die Rückmeldung <code>FunctionGroupState_{Function Group} (Verify)</code>.</li>\n<li>Status-Benachrichtigungen an die Diagnostic Application: Aufteilung in <code>CurrentStatus(Activating)</code> und <code>CurrentStatus(Activated)</code> anstelle von <code>CurrentStatus= :ACTIVATING</code>.</li>\n<li>Interne Aktivitäten: Ersetzung von <code>restartInstalledSoftwareIfNeeded()</code> und <code>swapPartitionsAndSynchronizeThem()</code> durch <code>Cleanup()</code> nach Aufruf von <code>Finish()</code>.</li>\n<li>Umbenennung des UCM-Service-Providers: Von <code>:UCM</code> zu <code>:External Reference</code>.</li>\n<li>Entfernung des UML-Rahmens <code>sd Activation</code>.</li>\n</ul>"}, {"from": "FIG-0c6ab6398bf753e6", "to": "FIG-9ef0817a813c9118", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Teilnehmerstruktur: Ersatz von <code>Diagnostic Application (OEM specific)</code> und <code>:External Reference</code> durch <code>UCM master</code> und <code>UCM sub 1</code>; State Management wird als <code>SM</code> modelliert (alle aus Paket <code>(from Actors)</code>).</li>\n<li>Interaktionsmodell: Umstellung auf eine Master-Subordinate-Architektur (<code>UCM master</code> koordiniert <code>UCM sub 1</code>).</li>\n<li>Zustandskontext: Einführung expliziter Zustandsregionen (<code>Ready</code>, <code>Activating</code>, <code>Verifying</code>, <code>Activated</code>, <code>Cleaning-up</code>).</li>\n<li>SM-Interaktionsprotokoll: Einführung der Methoden <code>StartUpdateSession()</code>, <code>PrepareUpdate(vector&lt;FunctionGroup&gt;)</code>, <code>VerifyUpdate(vector&lt;FunctionGroup&gt;)</code> und <code>StopUpdateSession()</code> anstelle von Event-Subscriptions auf <code>FunctionGroupState_{Function Group}</code>.</li>\n<li>Iterationen (<code>loop for each SoftwareCluster</code>): Sequenzierte Cluster-Vorbereitung (<code>PrepareUpdate</code>) und Cluster-Verifikation (<code>VerifyUpdate</code>).</li>\n<li>Verzweigung (<code>alt ReparseManifest</code>): Einführung der Alternativpfade <code>[Reset]</code> mit <code>ResetMachine()</code> und <code>[No Reset]</code> mit internem Aufruf <code>Reparse Manifests()</code>.</li>\n<li>Interne Aktionen: Ersetzung von <code>checkPackageDependencies()</code> durch <code>DependencyCheck()</code>; Ergänzung von <code>Symlinks or A/B switch()</code>.</li>\n<li>Rückmeldungen und Typen: Ersetzung typisierter Rückgabewerte (<code>:ActivateReturnType</code>, <code>:FinishReturnType</code>) durch ungetypte Aufrufe bzw. <code>:Activation success</code>.</li>\n</ul>"}]};
